  <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '40px 20px' }}>
    <section style={{ textAlign: 'center', marginBottom: '50px' }}>
      <span className="section-badge">Visual Showcase</span>
      <h1 className="gold-text" style={{ fontSize: '3rem', marginBottom: '15px' }}>Design & Installation Gallery</h1>
      <p style={{ color: '#aaa' }}>Browse high-resolution photographs of our real customer drape setups and mosquito screen installations.</p>
    </section>

    {/* Section 1: Dynamic ZIP Unpacked Portfolio */}
    <div style={{ marginBottom: '60px' }}>
      <h2 className="gold-text" style={{ fontSize: '1.8rem', marginBottom: '20px', textAlign: 'center' }}>
        Uploaded ZIP Portfolio Archive ({zipImages.length} Photos)
      </h2>

      {isLoading ? (
        <p style={{ textAlign: 'center', color: '#d4af37' }}>Unpacking photos from catalog.zip...</p>
      ) : zipImages.length > 0 ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
          {zipImages.map((img, idx) => (
            <div key={idx} className="animated-card" style={{ background: '#121212', border: '1px solid #333', borderRadius: '8px', overflow: 'hidden' }}>
              <img src={img.url} alt={img.name} style={{ width: '100%', height: '240px', objectFit: 'cover' }} />
              <div style={{ padding: '15px', fontSize: '0.85rem', color: '#888', textAlign: 'center' }}>{img.name}</div>
            </div>
          ))}
        </div>
      ) : (
        <p style={{ textAlign: 'center', color: '#666', fontStyle: 'italic' }}>
          Add catalog.zip to client/public/ to render catalog photos here.
        </p>
      )}
    </div>

    {/* Section 2: Standard Fixed Gallery Showcase */}
    <div style={{ borderTop: '1px solid #222', paddingTop: '50px' }}>
      <h2 className="gold-text" style={{ fontSize: '1.8rem', marginBottom: '30px', textAlign: 'center' }}>Curated Signature Projects</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '25px' }}>
        <div className="animated-card" style={{ background: '#121212', border: '1px solid #222', borderRadius: '8px', overflow: 'hidden' }}>
          <img src={GALLERY_IMAGES.sheerVoile} alt="Sheer Voile" style={{ width: '100%', height: '250px', objectFit: 'cover' }} />
          <div style={{ padding: '20px' }}><h4 className="gold-text">Translucent Daylight Sheers</h4></div>
        </div>
        <div className="animated-card" style={{ background: '#121212', border: '1px solid #222', borderRadius: '8px', overflow: 'hidden' }}>
          <img src={GALLERY_IMAGES.velvetDrapes} alt="Velvet Drapes" style={{ width: '100%', height: '250px', objectFit: 'cover' }} />
          <div style={{ padding: '20px' }}><h4 className="gold-text">Royal Velvet Bedroom Drapes</h4></div>
        </div>
        <div className="animated-card" style={{ background: '#121212', border: '1px solid #222', borderRadius: '8px', overflow: 'hidden' }}>
          <img src={GALLERY_IMAGES.balconyMesh} alt="Balcony Net" style={{ width: '100%', height: '250px', objectFit: 'cover' }} />
          <div style={{ padding: '20px' }}><h4 className="gold-text">Balcony Track Mosquito Screen</h4></div>
        </div>
      </div>
    </div>
  </div>
);

/* ==========================================================================
   5. CONTACT PAGE
   ========================================================================== */
const ContactPage = () => {
  const [formData, setFormData] = useState({ name: '', phone: '', email: '', service: 'Curtains', message: '' });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div style={{ maxWidth: '1000px', margin: '0 auto', padding: '40px 20px' }}>
      <section style={{ textAlign: 'center', marginBottom: '50px' }}>
        <span className="section-badge">Get In Touch</span>
        <h1 className="gold-text" style={{ fontSize: '3rem', marginBottom: '15px' }}>Request On-Site Consultation</h1>
        <p style={{ color: '#aaa' }}>Fill out the details below to schedule a technician visit with physical fabric swatches.</p>
      </section>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '40px' }}>
        <div style={{ background: '#121212', padding: '35px', borderRadius: '12px', border: '1px solid #222' }}>
          {submitted ? (
            <div style={{ textAlign: 'center', padding: '40px 0' }}>
              <h3 className="gold-text" style={{ fontSize: '1.8rem', marginBottom: '10px' }}>Thank You!</h3>
              <p style={{ color: '#aaa' }}>Our representative will call you shortly at <strong>{formData.phone}</strong> to confirm your slot.</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div>
                <label style={{ color: '#aaa', fontSize: '0.85rem', display: 'block', marginBottom: '6px' }}>Your Full Name</label>
                <input 
                  type="text" 
                  required 
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })} 
                  style={{ width: '100%', padding: '12px', background: '#0a0a0a', border: '1px solid #333', color: '#fff', borderRadius: '4px', boxSizing: 'border-box' }} 
                />
              </div>

              <div>
                <label style={{ color: '#aaa', fontSize: '0.85rem', display: 'block', marginBottom: '6px' }}>Phone Number</label>
                <input 
                  type="tel" 
                  required 
                  value={formData.phone} 
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })} 
                  style={{ width: '100%', padding: '12px', background: '#0a0a0a', border: '1px solid #333', color: '#fff', borderRadius: '4px', boxSizing: 'border-box' }} 
                />
              </div>

              <div>
                <label style={{ color: '#aaa', fontSize: '0.85rem', display: 'block', marginBottom: '6px' }}>Service Interest</label>
                <select 
                  value={formData.service} 
                  onChange={(e) => setFormData({ ...formData, service: e.target.value })} 
                  style={{ width: '100%', padding: '12px', background: '#0a0a0a', border: '1px solid #333', color: '#fff', borderRadius: '4px', boxSizing: 'border-box' }}
                >
                  <option value="Curtains">Custom Luxury Curtains</option>
                  <option value="Blackout">Blackout Linings</option>
                  <option value="Mosquito">Retractable Mosquito Mesh</option>
                  <option value="Full House">Full Home Window Package</option>
                </select>
              </div>

              <div>
                <label style={{ color: '#aaa', fontSize: '0.85rem', display: 'block', marginBottom: '6px' }}>Requirement Details / Address</label>
                <textarea 
                  rows="4" 
                  value={formData.message} 
                  onChange={(e) => setFormData({ ...formData, message: e.target.value })} 
                  style={{ width: '100%', padding: '12px', background: '#0a0a0a', border: '1px solid #333', color: '#fff', borderRadius: '4px', boxSizing: 'border-box' }} 
                />
              </div>

              <button type="submit" className="btn-gold" style={{ padding: '15px', width: '100%', cursor: 'pointer', fontSize: '1rem' }}>
                Submit Consultation Request
              </button>
            </form>
          )}
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px', justifyContent: 'center' }}>
          <div style={{ background: '#121212', padding: '25px', borderRadius: '10px', border: '1px solid #222' }}>
            <h4 className="gold-text" style={{ margin: '0 0 10px 0' }}>Call / WhatsApp Directly</h4>
            <p style={{ color: '#aaa', margin: 0 }}>+91 7502718156</p>
          </div>
          <div style={{ background: '#121212', padding: '25px', borderRadius: '10px', border: '1px solid #222' }}>
            <h4 className="gold-text" style={{ margin: '0 0 10px 0' }}>Showroom Address</h4>
            <p style={{ color: '#aaa', margin: 0 }}>Komarapalayam, Tamil Nadu, India</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
